# Homebrew formula for the Engra CLI. Generated by packaging/release.py in the
# release workflow; do not hand-edit. Release assets live in
# arenberg-engineering/engra-releases.
class Engra < Formula
  desc "AI coding agent and developer assistant for the terminal"
  homepage "https://engra.io"
  # Proprietary software of Arenberg AG, all rights reserved (LICENSE.txt).
  license :cannot_represent

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.38/engra-0.4.38-macos-arm64.tar.gz"
      sha256 "6a5a93c33c966f82ca2cf078542b62910d81e11f17f461f0bf8f16c1669f1017"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.38/engra-0.4.38-macos-x64.tar.gz"
      sha256 "4f63c5d391e4cdc8599b8ae66b7e4d1073e4034bbdd44fd91e171302d2069c0b"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.38/engra-0.4.38-linux-arm64.tar.gz"
      sha256 "046b9008add9c77d7d9552b3741c659d2f63c985a97e5509338c1a2245dd9723"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.38/engra-0.4.38-linux-x64.tar.gz"
      sha256 "448a29243eb05be499671855466e26a49af87a56614cacfa2708818137d90639"
    end
  end

  def install
    libexec.install "engra", "_internal"
    bin.install_symlink libexec/"engra"
    prefix.install "LICENSE.txt", "TERMS.md", "THIRD_PARTY_NOTICES.txt"
  end

  def caveats
    <<~EOS
      Sign in with:
        engra login

      Terms of Use: engra legal --terms

      Before uninstalling, run `engra logout` to remove saved credentials from
      the OS keychain. Settings and link state stay in ~/.config/engra (and
      doctor records in ~/.engra); remove them to clear everything.
    EOS
  end

  test do
    assert_equal "engra #{version}", shell_output("#{bin}/engra --version").strip
    assert_match "doctor", shell_output("#{bin}/engra --help")
    assert_match "Arenberg AG", shell_output("#{bin}/engra legal")
  end
end
